# Generated by scripts/bump-formula.py from upstream's GitHub releases — edit
# that, not this file. The daily bump re-renders it when upstream moves.
class Crw < Formula
  desc "Turn URLs into clean markdown or JSON — scrape, crawl, search, MCP server"
  homepage "https://github.com/us/crw"
  version "0.43.0"
  # Upstream declares the deprecated bare "AGPL-3.0" and ships AGPLv3 with no
  # "or later" clause, which is SPDX "AGPL-3.0-only".
  license "AGPL-3.0-only"

  # Prebuilt x86_64 Linux bottle so `brew install` pours it with no C compiler
  # (Homebrew-on-Linux otherwise requires one — a problem on atomic distros).
  # macOS and other arches fall back to upstream's url below; macOS always has
  # clang via the required Command Line Tools, so no bottle is needed.
  bottle do
    root_url "https://github.com/jakobhviid/homebrew-tap/releases/download/crw-0.43.0"
    sha256 cellar: :any_skip_relocation, x86_64_linux: "e8edc82900cb62b69dbfb088bfa4cedfdd8da129820fdffb480d8ac6df3998ff"
  end

  on_macos do
    on_arm do
      url "https://github.com/us/crw/releases/download/v0.43.0/crw-darwin-arm64.tar.gz"
      sha256 "69ccefcd93f1ff21e627f384d26d3675fbb6ac1202546b90d8a76d978705e828"
    end
    on_intel do
      url "https://github.com/us/crw/releases/download/v0.43.0/crw-darwin-x64.tar.gz"
      sha256 "b9989d27005bb709dbf7e69d83c137233a0a4a394a2cd637bba3694efed940b9"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/us/crw/releases/download/v0.43.0/crw-linux-arm64.tar.gz"
      sha256 "4fd033ca69379b37a92295a352f42efd559d32e6e6a7d3203d2f7020a6846d51"
    end
    on_intel do
      url "https://github.com/us/crw/releases/download/v0.43.0/crw-linux-x64.tar.gz"
      sha256 "4152ad6acb4b6d64475a80e576c6ce8596e8b6dd2efd17ae27e3f0c438c0b096"
    end
  end

  def install
    bin.install "crw"
  end

  def caveats
    <<~EOS
      crw runs fully locally — no account, no API key:

        crw example.com                 # page as markdown on stdout
        crw mcp                         # embedded MCP server for AI agents
        crw doctor                      # check renderer, search, proxy, ports

      When a page returns thin content, crw escalates to its own JS renderer and
      says so on stderr. Sites behind a Cloudflare challenge or DataDome return
      the interstitial rather than the article — clearing those needs a real
      browser session, not a renderer.

      `crw search` needs a backend: either a local one or the hosted CRW Cloud
      via `crw setup` (paid, with a free credit allowance). Scraping, crawling,
      mapping and the MCP server need none of it.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/crw --version")
  end
end
